import{_ as a,o as t,c as n,a1 as o}from"./chunks/framework.BwhMLafE.js";const h=JSON.parse('{"title":"Grammar Writing Guidelines","description":"","frontmatter":{},"headers":[],"relativePath":"grammar_guidelines.md","filePath":"grammar_guidelines.md"}'),i={name:"grammar_guidelines.md"};function s(r,e,l,c,d,p){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="grammar-writing-guidelines" tabindex="-1">Grammar Writing Guidelines <a class="header-anchor" href="#grammar-writing-guidelines" aria-label="Permalink to &quot;Grammar Writing Guidelines&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#1-file-structure--rule-syntax-grm-files">1. File Structure &amp; Rule Syntax (<code>.grm</code> files)</a></li><li><a href="#2-variable-naming--ast-generation">2. Variable Naming &amp; AST Generation</a></li><li><a href="#3-terminal-symbols">3. Terminal Symbols</a></li><li><a href="#4-procedure-hooks-procedure_name">4. Procedure Hooks (<code>@procedure_name</code>)</a></li><li><a href="#5-explicit-syntax-recovery-">5. Explicit Syntax Recovery (<code>@</code>)</a></li><li><a href="#6-indentation-sensitive-grammars">6. Indentation-Sensitive Grammars</a></li><li><a href="#7-operator-precedence--ambiguity-free-expression-extraction">7. Operator Precedence &amp; Ambiguity-Free Expression Extraction</a></li><li><a href="#8-verbatim-raw-capture">8. Verbatim Raw Capture (<code>@&gt;&gt;</code> / <code>@&gt;^&quot;...&quot;</code> / <code>@&gt;&quot;...&quot;^</code>)</a></li></ul><hr><p>This guide details the syntax, conventions, and compile-time annotations supported by this repository&#39;s parser generators (LL and LR).</p><hr><h2 id="_1-file-structure-rule-syntax-grm-files" tabindex="-1">1. File Structure &amp; Rule Syntax (<code>.grm</code> files) <a class="header-anchor" href="#_1-file-structure-rule-syntax-grm-files" aria-label="Permalink to &quot;1. File Structure &amp; Rule Syntax (\`.grm\` files)&quot;">​</a></h2><ul><li><p><strong>Rule Structure:</strong> Each grammar rule is defined by the LHS (Left-Hand Side) variable symbol on a single line, followed by its alternative productions.</p></li><li><p><strong>Unique Rule Headers:</strong> Each variable must have exactly one LHS header. Put all of its alternatives on consecutive <code>|</code> lines beneath that header; declaring the same LHS again is an error.</p></li><li><p><strong>Alternation:</strong> Each alternative production must start with a pipe character <code>|</code> on a new line, followed by space-separated symbols:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Value</span></span>
<span class="line"><span>| &quot;{&quot; OptionalBlank ObjectMembers OptionalBlank</span></span>
<span class="line"><span>| &quot;null&quot; OptionalBlank</span></span></code></pre></div></li><li><p><strong>Epsilon (Empty Productions):</strong> An empty production is represented by a single pipe <code>|</code> with no trailing symbols:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OptionalBlank</span></span>
<span class="line"><span>| space _OptionalBlankTail</span></span>
<span class="line"><span>|</span></span></code></pre></div></li><li><p><strong>Formatting:</strong> Rules must be separated by at least one blank line. The first variable defined in the file is automatically treated as the parser&#39;s entry point.</p></li></ul><hr><h2 id="_2-variable-naming-ast-generation" tabindex="-1">2. Variable Naming &amp; AST Generation <a class="header-anchor" href="#_2-variable-naming-ast-generation" aria-label="Permalink to &quot;2. Variable Naming &amp; AST Generation&quot;">​</a></h2><p>The parser generator statically configures the Abstract Syntax Tree (AST) node creation based on the naming style of the variable symbols:</p><ul><li><strong>PascalCase Validation:</strong> All variable names must be written in PascalCase. The generator validates this at compile-time.</li><li><strong>AST-Enabled Variables:</strong> Variables starting with a Capital letter (e.g. <code>Value</code>, <code>ObjectMembers</code>) allocate an AST node when matched.</li><li><strong>AST-Suppressed Helper Variables:</strong> Variables starting with an underscore (e.g. <code>_StringContent</code>, <code>_OptionalBlank</code>) are helper rules. The generator completely skips allocating AST nodes for them, optimizing runtime parsing performance and memory footprint.</li></ul><hr><h2 id="_3-terminal-symbols" tabindex="-1">3. Terminal Symbols <a class="header-anchor" href="#_3-terminal-symbols" aria-label="Permalink to &quot;3. Terminal Symbols&quot;">​</a></h2><p>Terminals in rules represent either exact character literals or pre-defined generative character classes:</p><ul><li><p><strong>Normal Terminals:</strong> Exact character/string matches are written in double quotes (e.g., <code>&quot;{&quot;</code>, <code>&quot;null&quot;</code>, <code>&quot;+&quot;</code>).</p><ul><li>Valid UTF-8 can be written directly (e.g., <code>&quot;سلام&quot;</code> or <code>&quot;😀&quot;</code>).</li><li><code>\\u{...}</code> inserts one Unicode scalar value using one to six hexadecimal digits (e.g., <code>&quot;\\u{1f600}&quot;</code>). Surrogate code points and values above <code>U+10FFFF</code> are rejected.</li><li>The double-quote character itself is written as a <code>&quot;\\u{22}&quot;</code> escape (also usable inside generative exceptions, e.g. <code>character^&quot;\\u{22}&quot;</code>).</li></ul></li><li><p><strong>Raw Strings:</strong> The raw-string form <code>\\&quot;~&quot;~&quot;</code> matches a literal <code>&quot;</code> with no escape decoding of its verbatim content. It is an alternative to <code>&quot;\\u{22}&quot;</code> and is useful when content would otherwise require heavy escaping; bundled grammars use the escaped spelling for readability.</p></li><li><p><strong>Generative Character Terminals:</strong> Unquoted keyword names map to specific sets of ASCII characters:</p><ul><li><code>digit</code>: Matches <code>&#39;0&#39;-&#39;9&#39;</code></li><li><code>hex_digit</code>: Matches <code>&#39;0&#39;-&#39;9&#39;</code>, <code>&#39;a&#39;-&#39;f&#39;</code>, and <code>&#39;A&#39;-&#39;F&#39;</code></li><li><code>letter</code>: Matches <code>&#39;a&#39;-&#39;z&#39;</code> and <code>&#39;A&#39;-&#39;Z&#39;</code></li><li><code>lowercase_letter</code>: Matches <code>&#39;a&#39;-&#39;z&#39;</code></li><li><code>uppercase_letter</code>: Matches <code>&#39;A&#39;-&#39;Z&#39;</code></li><li><code>whitespace</code>: Matches whitespace characters (<code>\\t</code>, <code>\\n</code>, <code>\\r</code>, <code>\\x0b</code>, <code>\\x0c</code>, <code></code>)</li><li><code>punctuation</code>: Matches standard punctuation characters</li><li><code>character</code>: Matches letters, digits, punctuation, and whitespace</li><li><code>operator</code>: Matches operator symbols (<code>+</code>, <code>*</code>, <code>/</code>, <code>&amp;</code>, <code>|</code>, <code>&gt;</code>, <code>&gt;=</code>, <code>&lt;</code>, <code>&lt;=</code>, <code>=</code>)</li><li><code>new_line</code>: Matches <code>\\n</code></li><li><code>space</code>: Matches space <code>&#39; &#39;</code></li><li><code>block_start</code>: Matches control character <code>\\x01</code> (representing the start of a block when indentation syntax is enabled for the parser, see <a href="./configuration.html#language-configuration">Language Configuration</a> for details)</li><li><code>block_end</code>: Matches control character <code>\\x02</code> (representing the end of a block when indentation syntax is enabled for the parser, see <a href="./configuration.html#language-configuration">Language Configuration</a> for details)</li></ul></li><li><p><strong>UTF-8 Byte-Class Terminals:</strong> These single-byte generative terminals can be composed into grammar rules that accept every valid UTF-8 scalar while rejecting overlong encodings, surrogate encodings, and values above <code>U+10FFFF</code>:</p><ul><li><code>utf8_lead_two</code>: Two-byte sequence leads (<code>0xC2</code>-<code>0xDF</code>)</li><li><code>utf8_lead_three_general</code>: General three-byte leads (<code>0xE1</code>-<code>0xEC</code>, <code>0xEE</code>-<code>0xEF</code>)</li><li><code>utf8_lead_four_general</code>: General four-byte leads (<code>0xF1</code>-<code>0xF3</code>)</li><li><code>utf8_continuation</code>: Any continuation byte (<code>0x80</code>-<code>0xBF</code>)</li><li><code>utf8_continuation_80_8f</code>, <code>utf8_continuation_80_9f</code>, <code>utf8_continuation_90_bf</code>, and <code>utf8_continuation_a0_bf</code>: Restricted continuation ranges used at UTF-8 boundary cases</li></ul><p>See <code>languages/json-unicode/ll.grm</code> and <code>languages/json-unicode/lr.grm</code> for complete LL and LR scalar rules built from these terminals.</p></li><li><p><strong>Generative Suffix Exceptions:</strong> Any generative terminal can have exceptions appended as a suffix chain introduced by the <code>^</code> character followed by a normal terminal (e.g., <code>character^&quot;\\n&quot;</code>, <code>character^&quot;\\u{22}&quot;</code>, or multiple chained exceptions like <code>digit^&quot;1&quot;^&quot;3&quot;</code>). The exception terminal&#39;s characters are excluded from the allowed terminal characters of the generative class. Exception terminals use the same escape rules as normal terminals, so content is decoded once per exception rather than re-scanned from flattened text.</p></li><li><p><strong>Raw Strings:</strong> A <code>&quot;</code> character inside a grammar can also be matched with the raw-string form <code>\\&quot;~&quot;~&quot;</code>, whose content is taken verbatim (no escape decoding).</p></li></ul><hr><h2 id="_4-procedure-hooks-procedure-name" tabindex="-1">4. Procedure Hooks (<code>@procedure_name</code>) <a class="header-anchor" href="#_4-procedure-hooks-procedure-name" aria-label="Permalink to &quot;4. Procedure Hooks (\`@procedure_name\`)&quot;">​</a></h2><p>Galley provides three explicit hook placements, registered by appending a procedure name with <code>@</code>, and a fourth family of automatic reduction hooks:</p><ol><li><p><strong>LHS Variable Hook:</strong> Attaches to the left-hand-side variable definition, executing whenever this variable is reduced anywhere:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Value@dropChildren</span></span>
<span class="line"><span>| Object OptionalBlank</span></span>
<span class="line"><span>| Array OptionalBlank</span></span></code></pre></div></li><li><p><strong>RHS Symbol Hook:</strong> Attaches to a right-hand-side symbol (either a variable, or a terminal symbol if <code>--ast-for-terminals</code> is active), executing only when matched in that position:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Parent</span></span>
<span class="line"><span>| Value Child@validateChild &quot;]&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Number</span></span>
<span class="line"><span>| digit@recordDigit _PositiveIntegerNumberTail</span></span></code></pre></div></li><li><p><strong>Production Hook:</strong> Attaches to the left-hand-side variable for a specific right-hand-side production. It is placed immediately after the pipe (<code>|</code>) and executes on the resulting left-hand-side node only when that particular production is reduced:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FloatTail</span></span>
<span class="line"><span>|@normalizeFraction &quot;.&quot; PositiveIntegerNumber</span></span>
<span class="line"><span>|</span></span></code></pre></div></li><li><p><strong>Automatic Reduction Hooks:</strong> Exporting conventionally named public procedures from <code>procedures.zig</code> binds them without grammar annotations:</p><ul><li><code>reduction_&lt;SymbolName&gt;_&lt;RhsIndex&gt;</code> runs only for the zero-based production index of that symbol. Indices follow the consecutive <code>|</code> lines beneath the variable&#39;s unique LHS header.</li><li><code>reduction_&lt;SymbolName&gt;</code> runs whenever that symbol produces an AST node.</li><li><code>reduction</code> runs for every eligible variable reduction and AST-enabled terminal match.</li></ul></li></ol><p>Multiple procedures can be chained on any explicit hook target (for example, <code>Number@hook1@hook2</code>). Chaining runs the procedures from left to right; it is not a separate hook kind.</p><p>For each variable reduction, hooks run in this order: RHS occurrence hooks, production hooks, <code>reduction_&lt;SymbolName&gt;_&lt;RhsIndex&gt;</code>, LHS hooks, <code>reduction_&lt;SymbolName&gt;</code>, then the general <code>reduction</code> hook. Each explicit chain runs left to right, and each phase receives the node produced by the preceding phase.</p><p>For an AST-enabled terminal, the occurrence chain runs first, followed by <code>reduction_&lt;SymbolName&gt;</code> and then <code>reduction</code>. Terminal hooks receive <code>args.rule = null</code>. LR generation reports <code>error.AmbiguousProcedureHooks</code> if the parser cannot distinguish occurrences with different chains at the match or reduction point.</p><hr><p>For detailed information on automatic hooks, nested reduction ordering, compiler AST requirements, and how to write hook functions in Zig, see the <a href="./procedures.html">Reduction Procedures User Guide</a>.</p><h2 id="_5-explicit-syntax-recovery" tabindex="-1">5. Explicit Syntax Recovery (<code>@</code>) <a class="header-anchor" href="#_5-explicit-syntax-recovery" aria-label="Permalink to &quot;5. Explicit Syntax Recovery (\`@\`)&quot;">​</a></h2><p>Recovery annotations declare synchronization terminals on an LHS variable, a production, or an RHS variable occurrence:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Statement@!^&quot;}&quot;@!&quot;;&quot;^@hook</span></span>
<span class="line"><span>|@!&quot;,&quot;^ Expression</span></span>
<span class="line"><span>| Block Statement@!^&quot;}&quot;</span></span></code></pre></div><ul><li><code>@!^&quot;}&quot;</code> resumes immediately before <code>}</code> and preserves the terminal for the surrounding parser state.</li><li><code>@!&quot;;&quot;^</code> resumes immediately after <code>;</code> and consumes the terminal.</li><li>Consecutive annotations provide multiple candidates for one target.</li><li>Recovery terminals accept the same two quoted exact-terminal forms as normal grammar terminals. Empty terminals, NUL-containing terminals, and generative terminals are invalid.</li><li>An RHS recovery annotation may only attach to a variable occurrence, not a terminal occurrence.</li></ul><p>When error recovery is enabled and the grammar has no annotations, Galley uses automatic recovery. The presence of any recovery annotation selects explicit-only recovery for the generated parser; an error outside committed annotated scopes fails immediately without automatic fallback. When error recovery is disabled, annotations remain in the grammar model but are inert at runtime; the generated parser is still valid and selects disabled mode, and the CLI emits a warning at generation time if the grammar contains recovery annotations but recovery is disabled.</p><p>After a mismatch, Galley tries committed scopes from the most specific to the most general: the active RHS occurrence, its selected production, its LHS variable, then enclosing reductions. Within one target it chooses the earliest candidate in the input, then the longest terminal, then source order. A successful recovery preserves the original mismatch diagnostic, adds structured recovery context, neutral-completes the damaged variable, and skips hooks belonging to the damaged occurrence, production, and variable.</p><p>Galley&#39;s own <a href="https://github.com/sanbus-org/galley/blob/main/languages/galley/ll.grm" target="_blank" rel="noreferrer">LL grammar</a> and <a href="https://github.com/sanbus-org/galley/blob/main/languages/galley/lr.grm" target="_blank" rel="noreferrer">LR grammar</a> are maintained examples. They recover a damaged <code>Symbol</code> before its newline, discard a damaged <code>RightHandSideLine</code> after its newline, and fall back from a damaged <code>Rule</code> to the blank line before the next rule. Run <code>zig build compare-galley-recovery</code> to see the annotated LL grammar and an annotation-free clone parse the same malformed grammar in explicit and automatic modes.</p><hr><h2 id="_6-indentation-sensitive-grammars" tabindex="-1">6. Indentation-Sensitive Grammars <a class="header-anchor" href="#_6-indentation-sensitive-grammars" aria-label="Permalink to &quot;6. Indentation-Sensitive Grammars&quot;">​</a></h2><p>Set <code>pub const indentation_syntax = true;</code> in <code>config.zig</code> to make the generated lexer translate line indentation into explicit block tokens. Grammar rules then match them through three generative terminals:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Terminal</th><th style="text-align:left;">Byte</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>block_start</code></td><td style="text-align:left;"><code>\\x01</code></td><td style="text-align:left;">One level of indentation was opened.</td></tr><tr><td style="text-align:left;"><code>block_end</code></td><td style="text-align:left;"><code>\\x02</code></td><td style="text-align:left;">One level of indentation was closed.</td></tr><tr><td style="text-align:left;"><code>new_line</code></td><td style="text-align:left;"><code>\\n</code></td><td style="text-align:left;">A line boundary at the same indentation level.</td></tr></tbody></table><p>Galley&#39;s <code>languages/indentation/ll.grm</code> is a maintained example: blocks are written as <code>block_start Fields block_end</code>, and a sequence of same-level rows joins them with <code>new_line</code>.</p><h3 id="tokenization-rules" tabindex="-1">Tokenization Rules <a class="header-anchor" href="#tokenization-rules" aria-label="Permalink to &quot;Tokenization Rules&quot;">​</a></h3><ul><li><p>Indentation is measured <strong>only on lines that follow a newline</strong>. The very first line of a file has no preceding newline, so its leading spaces are ordinary <code>&#39; &#39;</code> tokens, not indentation.</p></li><li><p>Only literal ASCII spaces count. Leading tabs are not indentation; a line that begins with a tab is treated as being at level 0, and the tab itself is tokenized normally.</p></li><li><p><code>indent_width</code> snaps to the leading-space count of the first line that follows a newline. Every later line&#39;s leading spaces must be an integer multiple of that width; otherwise parsing fails with a structured <code>IndentationError</code> (&quot;N spaces are not divisible by the detected indentation width of M&quot;).</p></li><li><p>Each line&#39;s indentation level is <code>leading_spaces / indent_width</code>. Compared with the previous line&#39;s level:</p><ul><li>same level → one <code>new_line</code> token;</li><li><code>k</code> levels deeper → <code>k</code> <code>block_start</code> tokens;</li><li><code>k</code> levels shallower → <code>k</code> <code>block_end</code> tokens.</li></ul><p>The leading spaces themselves are consumed and never appear as tokens.</p></li><li><p>A blank line (zero leading spaces) closes every open block with one <code>block_end</code> each, snapping the level to 0; the next indented line re-opens the blocks with <code>block_start</code> tokens. So blocks that must survive blank lines cannot be written directly — the grammar must accept the close/reopen pair.</p></li><li><p>End of input emits no implicit closing tokens. A grammar that expects a block to be closed must match the trailing <code>block_end</code>s itself.</p></li></ul><hr><h2 id="_7-operator-precedence-ambiguity-free-expression-extraction" tabindex="-1">7. Operator Precedence &amp; Ambiguity-Free Expression Extraction <a class="header-anchor" href="#_7-operator-precedence-ambiguity-free-expression-extraction" aria-label="Permalink to &quot;7. Operator Precedence &amp; Ambiguity-Free Expression Extraction&quot;">​</a></h2><p>The most common source of grammar ambiguity is a <strong>shared operator nonterminal</strong> used by more than one precedence level:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Expression</span></span>
<span class="line"><span>| Expression Operator Expression</span></span>
<span class="line"><span>| &quot;(&quot; Expression &quot;)&quot;</span></span>
<span class="line"><span>| Number</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Operator</span></span>
<span class="line"><span>| &quot;+&quot;</span></span>
<span class="line"><span>| &quot;*&quot;</span></span></code></pre></div><p>Because both <code>+</code> and <code>*</code> collapse into one <code>Operator</code> symbol, the parser cannot tell them apart at a single decision point: the LL planner reports <code>ambiguous grammar: variable &lt;X&gt;, terminal &quot;&lt;t&gt;&quot; matches two productions</code>, and the LR planner reports conflicting shift/reduce actions. There is no grammar annotation that rescues this shape — the fix is structural.</p><h3 id="rule-1-give-each-precedence-level-its-own-operator" tabindex="-1">Rule 1: Give each precedence level its own operator <a class="header-anchor" href="#rule-1-give-each-precedence-level-its-own-operator" aria-label="Permalink to &quot;Rule 1: Give each precedence level its own operator&quot;">​</a></h3><p>Split the shared <code>Operator</code> into one nonterminal per precedence level and nest the levels so the tighter-binding operators are lower:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Expression</span></span>
<span class="line"><span>| Expression &quot;+&quot; Term</span></span>
<span class="line"><span>| Term</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Term</span></span>
<span class="line"><span>| Term &quot;*&quot; Factor</span></span>
<span class="line"><span>| Factor</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Factor</span></span>
<span class="line"><span>| &quot;(&quot; Expression &quot;)&quot;</span></span>
<span class="line"><span>| Number</span></span></code></pre></div><p>Now <code>+</code> and <code>*</code> are distinct terminals at distinct levels, and the nesting (<code>Expression</code> → <code>Term</code> → <code>Factor</code>) encodes precedence directly.</p><h3 id="rule-2-ll-1-additionally-requires-the-grammar-to-be-left-factored" tabindex="-1">Rule 2: LL(1) additionally requires the grammar to be left-factored <a class="header-anchor" href="#rule-2-ll-1-additionally-requires-the-grammar-to-be-left-factored" aria-label="Permalink to &quot;Rule 2: LL(1) additionally requires the grammar to be left-factored&quot;">​</a></h3><p>The LR generator accepts the left-recursive form above. The LL generator does not: productions sharing a prefix — including <code>Expression | Expression &quot;+&quot; Term | Term</code>, which both start with <code>Expression</code> — conflict in their FIRST sets. For LL, hoist the recursion into a tail nonterminal and factor shared prefixes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Expression</span></span>
<span class="line"><span>| Term ExpressionTail</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ExpressionTail</span></span>
<span class="line"><span>| &quot;+&quot; Term ExpressionTail</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Term</span></span>
<span class="line"><span>| Factor TermTail</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TermTail</span></span>
<span class="line"><span>| &quot;*&quot; Factor TermTail</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Factor</span></span>
<span class="line"><span>| &quot;(&quot; Expression &quot;)&quot;</span></span>
<span class="line"><span>| Number</span></span></code></pre></div><p>When two productions of a variable do share a nonempty prefix, the LL generator applies that rewrite automatically: it hoists the shared prefix and plans from the factored grammar, expanding the <code>&lt;Variable&gt;_Tail</code> alternatives inline at the single parent call site. The helper builds no node and needs no hooks — suffix children splice directly into the parent, so the tree and the surviving <code>reduction_&lt;Var&gt;_&lt;N&gt;</code> hook are identical to the unfactored shape. The merged hook can no longer tell which alternative matched except through its children, exactly as with a hand-factored grammar minus the tail hooks. Generation still warns with the suggested rewrite only when automatic factoring cannot preserve behavior: the prefix occurrences carry different annotations, a production carries its own annotations, or the overlap is indirect (terminals shared through different derivation chains rather than a common RHS prefix). as in:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>warning: ambiguous grammar: variable Root, terminal &quot;:&quot; matches two productions:</span></span>
<span class="line"><span>  Root -&gt; &quot;:&quot; Fields ActionTail</span></span>
<span class="line"><span>  Root -&gt; &quot;:&quot; ActionTail</span></span>
<span class="line"><span>warning:   suggestion: left-factor the shared prefix</span></span>
<span class="line"><span>  Root -&gt; &quot;:&quot; Root_Tail</span></span>
<span class="line"><span>  Root_Tail -&gt; Fields ActionTail</span></span>
<span class="line"><span>  Root_Tail -&gt; ActionTail</span></span></code></pre></div><h3 id="rule-3-keep-mixed-associativity-operators-at-separate-levels" tabindex="-1">Rule 3: Keep mixed-associativity operators at separate levels <a class="header-anchor" href="#rule-3-keep-mixed-associativity-operators-at-separate-levels" aria-label="Permalink to &quot;Rule 3: Keep mixed-associativity operators at separate levels&quot;">​</a></h3><p>Operators that associate differently (e.g. left-associative <code>-</code>, right-associative <code>^</code>) must live at different precedence levels, each with its own recursion direction (right recursion for right-associativity in LL, left recursion for left-associativity in LR).</p><p>Galley&#39;s <code>languages/indentation/ll.grm</code> demonstrates the per-level pattern with <code>Expression</code> / <code>ExpressionTail</code>, <code>OperandAndNumber</code>, and <code>Operand</code>/<code>OperandTail</code> for suffix calls, list gets, and casts.</p><hr><h2 id="_8-verbatim-raw-capture" tabindex="-1">8. Verbatim Raw Capture (<code>@&gt;&gt;</code> / <code>@&gt;^&quot;...&quot;</code> / <code>@&gt;&quot;...&quot;^</code>) <a class="header-anchor" href="#_8-verbatim-raw-capture" aria-label="Permalink to &quot;8. Verbatim Raw Capture (\`@&gt;&gt;\` / \`@&gt;^&quot;...&quot;\` / \`@&gt;&quot;...&quot;^\`)&quot;">​</a></h2><p>Annotate an RHS occurrence with the verbatim marker <code>@&gt;&gt;</code> (derived terminator) or a literal terminator with a <code>^</code> cursor marker (<code>@&gt;^&quot;...&quot;</code> or <code>@&gt;&quot;...&quot;^</code>) to consume a raw block of source bytes opaquely. For <code>@&gt;&gt;</code>, the occurrence still matches normally and the bytes it matched become a terminator; the parser captures every raw byte from just after the terminator until the terminator reappears in the input, then resumes the remaining RHS. For a literal terminator, the given terminal is the fixed terminator and the annotated symbol is the anchor.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Program</span></span>
<span class="line"><span>| &quot;&lt;&lt;&lt;&quot; UpperPair@&gt;&gt; LowerTail</span></span>
<span class="line"><span>| &quot;]]]&quot; &quot;%%&quot;@&gt;&gt; LowerTail</span></span>
<span class="line"><span>| &quot;{{{&quot; UpperPair@&gt;^&quot;/&gt;&quot; LowerTail</span></span>
<span class="line"><span>| &quot;(((&quot; UpperPair@&gt;&quot;\\n&quot;^ LowerTail</span></span></code></pre></div><ul><li>The marker grammar lexes only the three marker forms: <code>@&gt;&gt;</code> (derived) and <code>@&gt;^ &quot;...&quot;</code> / <code>@&gt;&quot;...&quot;^</code> (literal terminator with the cursor marker before or after the terminal). Any other marker text is a syntax error in the galley grammar itself.</li><li>The annotated symbol may be a variable occurrence (<code>UpperPair@&gt;&gt;</code>) or a terminal occurrence (<code>&quot;%%&quot;@&gt;&gt;</code>). For a variable with <code>@&gt;&gt;</code>, the terminator is the exact source bytes the variable matched; for a terminal, the terminal&#39;s literal bytes. A literal terminator is exactly the terminal&#39;s bytes.</li><li>The <code>^</code> position chooses whether the terminator is part of the captured body. A <code>^</code> after the terminator (<code>@&gt;&quot;...&quot;^</code>) appends the terminator to the body; a <code>^</code> before the terminator (<code>@&gt;^&quot;...&quot;</code>) leaves the terminator in the input for the parser to match next. The same prefix/suffix rules select the recovery anchor with <code>^</code> on recovery points.</li><li>The captured body is not lexed: no tokenization, indentation translation, or escape decoding applies inside it. The search for the reappearing terminator is byte-exact and case-sensitive, and stops at the first occurrence.</li><li>With <code>@&gt;&quot;...&quot;^</code> the captured span includes the terminator bytes and the cursor is left directly past them. With <code>@&gt;^&quot;...&quot;</code> the captured span excludes the terminator and the terminator bytes remain in the input stream for the parser to match (the cursor is left at the start of the terminator).</li><li>A derived terminator must come from a non-empty, non-nullable symbol; generation fails with <code>error.EmptyVerbatimSymbol</code>. A literal terminator must be non-empty and contain no NUL bytes; generation fails with <code>error.EmptyVerbatimTerminator</code> or <code>error.NulVerbatimTerminator</code>.</li><li>An unterminated capture raises <code>error.UnterminatedRawString</code>, reporting the terminator bytes as the expected tokens.</li></ul><p>Semantic span: the annotated symbol&#39;s node covers only the anchor terminator symbol&#39;s own matched bytes (for example <code>EN</code> in <code>&lt;&lt;&lt;EN...</code>); the captured body is consumed but does not extend the symbol&#39;s span. The enclosing rule&#39;s node still spans the entire production, body included.</p><p>Parser notes:</p><ul><li>The LL generator supports verbatim capture with or without AST and procedures.</li><li>At runtime, LR parses a variable terminator by reducing it as a default action, because the captured body may begin with any byte; a literal terminator keeps the anchor short and is often the simpler LR shape.</li><li>Verbatim capture keeps the entire input in memory: source retention is enabled automatically and input streaming is disabled for parsers that use verbatim capture.</li></ul><p>Galley&#39;s own grammar demonstrates the syntax; <code>tests/verbatim/grammar.grm</code> is a maintained example with plain and indentation-mode test fixtures.</p>`,65)])])}const m=a(i,[["render",s]]);export{h as __pageData,m as default};
